package emit

import (
	"fmt"
	"strings"

	"github.com/wippyai/go-lua/analysis/schema/axis/member"
	"github.com/wippyai/go-lua/analysis/schema/axis/member/definition"
	"github.com/wippyai/go-lua/analysis/schema/rule/program"
)

// The emitted identifiers. They are fixed rather than derived from the rule
// key for one reason: a package holds one rule's family, and a stable name set
// keeps a regenerated file a diff of its declaration rather than of its
// spelling.
const (
	reducerType   = "familyReducer"
	rowType       = "familyRow"
	familyType    = "sealedFamily"
	workerType    = "familyWorker"
	installerType = "familyInstaller"
	constructor   = "NewFamilyInstaller"
)

// render writes one emission plan as Go source. The import block is rendered
// last because every qualifier is registered while the body is written.
func render(built *plan) ([]byte, error) {
	imports := built.imports
	imports.reserve(built.target.PackageName)
	var body strings.Builder
	if err := renderReducer(&body, built); err != nil {
		return nil, err
	}
	if err := renderRow(&body, built); err != nil {
		return nil, err
	}
	renderFamily(&body, built)
	if built.shape == shapeExactFold {
		renderExactTuples(&body, built)
	}
	if err := renderWorker(&body, built); err != nil {
		return nil, err
	}
	for _, join := range declaredDerivations(built) {
		if err := renderDeclaredDerivation(&body, built, join); err != nil {
			return nil, err
		}
	}
	if err := renderInstaller(&body, built); err != nil {
		return nil, err
	}
	var out strings.Builder
	fmt.Fprintf(&out, "// Code generated by the rule family emitter from the %q rule declaration; DO NOT EDIT.\n",
		string(built.target.Spec.Key))
	out.WriteString("//\n")
	out.WriteString("// The installer seals every primitive through the plane at the geometry the\n")
	out.WriteString("// declaration states, the family holds one sealed row per plan row, and the\n")
	out.WriteString("// worker performs one invocation over lane-owned scratch. The semantic fold\n")
	out.WriteString("// this file calls, and the relation derivations its joins name, remain the\n")
	out.WriteString("// owner's own source.\n\n")
	fmt.Fprintf(&out, "package %s\n\n", built.target.PackageName)
	out.WriteString(imports.block())
	out.WriteString(body.String())
	return []byte(out.String()), nil
}

// sliceView spells the slice marker a many-valued delivery carries when its
// read established one cell per member. A whole-vector read delivers one
// vector and carries none.
// manyValuedArgument answers the declared argument of one fold input when that
// input is delivered as a whole many-valued view rather than as one cell.
func manyValuedArgument(built *plan, input int) (definition.Argument, bool) {
	for _, argument := range built.fold.arguments {
		if argument.Role == definition.ArgumentVector && argument.Input == input {
			return argument, true
		}
	}
	return definition.Argument{}, false
}

func sliceView(argument definition.Argument) string {
	if argument.Slice {
		return "[]"
	}
	return ""
}

// reducerFields is the state one invocation seals into the emitted reducer:
// the candidate carrier when the fold declares one, and every fold input the
// reducer's own delivery does not carry.
func reducerFields(built *plan) []string {
	fields := make([]string, 0, len(built.fold.arguments))
	for _, argument := range built.fold.arguments {
		if argument.Role == definition.ArgumentCandidate {
			fields = append(fields, "candidate")
			continue
		}
		if argument.Role != definition.ArgumentFact && argument.Role != definition.ArgumentVector {
			continue
		}
		if _, delivered := built.deliveredFact[argument.Input]; delivered {
			continue
		}
		fields = append(fields, fmt.Sprintf("input%d", built.fold.inputs[argument.Input].position))
	}
	return fields
}

func renderReducer(out *strings.Builder, built *plan) error {
	imports := built.imports
	out.WriteString("// " + reducerType + " is the sealed semantic half of one invocation. It holds the\n")
	out.WriteString("// carriers this row's fold is indexed by, and its type is the family's, so the\n")
	out.WriteString("// call below is a static direct call rather than an interface dispatch.\n")
	if built.fold.state != nil {
		out.WriteString("//\n")
		out.WriteString("// It also carries the state the declared judgment is issued by. That state is\n")
		out.WriteString("// the family's, sealed once from the axis schemas the declaration names, so a\n")
		out.WriteString("// fold resting on cold owner knowledge still takes only carriers as arguments.\n")
	}
	fmt.Fprintf(out, "type %s struct {\n", reducerType)
	if built.fold.state != nil {
		fmt.Fprintf(out, "\tstate %s\n", imports.typeName(built.fold.state.state))
	}
	for _, argument := range built.fold.arguments {
		if argument.Role == definition.ArgumentCandidate {
			fmt.Fprintf(out, "\tcandidate %s\n", imports.typeName(argument.Type))
			continue
		}
		if argument.Role == definition.ArgumentVector {
			if _, delivered := built.deliveredFact[argument.Input]; delivered {
				continue
			}
			fmt.Fprintf(out, "\tinput%d %s%s[%s]\n", built.fold.inputs[argument.Input].position,
				sliceView(argument), imports.typeName(argument.Type), imports.typeName(argument.Element))
			continue
		}
		if argument.Role != definition.ArgumentFact {
			continue
		}
		if _, delivered := built.deliveredFact[argument.Input]; delivered {
			continue
		}
		fmt.Fprintf(out, "\tinput%d %s\n", built.fold.inputs[argument.Input].position, imports.typeName(argument.Type))
	}
	out.WriteString("}\n\n")

	switch built.shape {
	case shapeCarry:
		if len(built.joins) == 0 {
			return renderSourceCarryReduce(out, built)
		}
		return renderCarryReduce(out, built)
	case shapeExactFold:
		return renderExactReduce(out, built)
	case shapeSelectedExact:
		return renderSelectedExactReduce(out, built)
	case shapeSelectedRoute:
		return renderRouteReduce(out, built)
	case shapeStructural:
		return renderStructuralReduce(out, built)
	default:
		return unexpressible(built.target.Spec.Key, "an unclassified fold", "the declaration derives no emitted shape")
	}
}

func renderExactReduce(out *strings.Builder, built *plan) error {
	imports := built.imports
	structure := imports.use(structurePackagePath)
	for _, read := range built.joins {
		if read.read.Contract.Sparse != program.SparseExplicit {
			return unexpressible(built.target.Spec.Key, fmt.Sprintf("an exact fold read with %s sparsity", sparseName(read.read.Contract.Sparse)),
				"the exact fold preserves absence and never materializes a default")
		}
	}
	if len(built.fold.results) != 2 {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("an exact fold answering %d results", len(built.fold.results)),
			"an exact fold publishes one fact and one disposition")
	}
	call, err := foldCall(built)
	if err != nil {
		return err
	}
	parameters := make([]string, 0, len(built.fold.inputs))
	for index, join := range built.fold.inputs {
		// A many-valued input arrives as the view its own read established -
		// the ONE statement of that choice is the declaration's, and the
		// signature restates it here rather than deciding again. A spanned
		// vector is that case: what the fold receives is the whole delivery,
		// not one of its cells.
		if argument, many := manyValuedArgument(built, index); many {
			parameters = append(parameters, join.name+"Vector "+sliceView(argument)+imports.typeName(argument.Type)+"["+imports.typeName(argument.Element)+"]")
			continue
		}
		parameters = append(parameters, exactCellName(join)+" "+imports.typeName(join.axis.fact))
	}
	out.WriteString("// Reduce is the one irreducible typed judgment of this exact family. It is\n")
	out.WriteString("// called once per cell of the canonical product its declared reads refine, and\n")
	out.WriteString("// the worker authenticates presence before calling it, so absence never becomes\n")
	out.WriteString("// a default fact and the fold receives only declared carriers.\n")
	fmt.Fprintf(out, "func (fold %s) Reduce(%s) (%s, %s.ReductionOutcome) {\n",
		reducerType, strings.Join(parameters, ", "), imports.typeName(built.fold.results[0]), structure)
	fmt.Fprintf(out, "\treturn %s\n}\n\n", call)
	return nil
}

// foldCall spells the one direct call to the declared reducer, with the
// argument vector the declaration derives and nothing beside it.
func foldCall(built *plan) (string, error) {
	imports := built.imports
	arguments := make([]string, 0, len(built.fold.arguments))
	for _, argument := range built.fold.arguments {
		switch argument.Role {
		case definition.ArgumentCandidate:
			arguments = append(arguments, "fold.candidate")
		case definition.ArgumentBranch:
			// The branch ordinal is the invocation's own, handed over by the
			// fold primitive. It is never a field: a reducer sealed with one
			// would answer for the branch it was built for rather than the one
			// it was asked about.
			arguments = append(arguments, "branch")
		case definition.ArgumentFact:
			expression, present := built.deliveredFact[argument.Input]
			if !present {
				expression = fmt.Sprintf("fold.input%d", built.fold.inputs[argument.Input].position)
			}
			arguments = append(arguments, expression)
		case definition.ArgumentTag:
			expression, present := built.deliveredTag[argument.Input]
			if !present {
				return "", unexpressible(built.target.Spec.Key, "a tagged fold input outside its own selection",
					fmt.Sprintf("input %d declares a tag, and only the selection this row publishes through delivers one", argument.Input))
			}
			arguments = append(arguments, expression)
		case definition.ArgumentRoute:
			expression, present := built.deliveredRoute[argument.Input]
			if !present {
				return "", unexpressible(built.target.Spec.Key, "a routed fold input outside its own route selection",
					fmt.Sprintf("input %d declares a route carrier, and only the selected relation member owns a destination coordinate", argument.Input))
			}
			arguments = append(arguments, expression)
		case definition.ArgumentVector:
			// A many-valued input is one argument. An invocation that fills
			// the reducer's field hands the fold that field; one that
			// materializes the delivery in the worker hands it that, so the
			// fold reads the same view either way and never a copy of it.
			expression, present := built.deliveredFact[argument.Input]
			if !present {
				expression = fmt.Sprintf("fold.input%d", built.fold.inputs[argument.Input].position)
			}
			arguments = append(arguments, expression)
		default:
			return "", unexpressible(built.target.Spec.Key, "an unknown fold argument role", fmt.Sprintf("input %d", argument.Input))
		}
	}
	receiver := ""
	if built.fold.state != nil {
		receiver = "fold.state"
	}
	return imports.call(built.fold.reducer.Implementation, receiver, arguments...), nil
}

func renderCarryReduce(out *strings.Builder, built *plan) error {
	imports := built.imports
	structure := imports.use(structurePackagePath)
	read := built.joins[0]
	// FoldCarry delivers the exact cell to Reduce itself, so this shape has no
	// call site to seal a materialization policy at. Only an explicitly sparse
	// read is therefore expressible here: its absence is delivered unchanged,
	// which is the one reading that needs no substitution.
	if read.read.Contract.Sparse != program.SparseExplicit {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("an exact carry read with %s sparsity", sparseName(read.read.Contract.Sparse)),
			"the carry fold hands sparse absence to the domain, and the fold primitive seals no cell policy to substitute through")
	}
	if len(built.fold.results) != 2 {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("a carry fold answering %d results", len(built.fold.results)),
			"a carry fold publishes one fact and one disposition")
	}
	call, err := foldCall(built)
	if err != nil {
		return err
	}
	out.WriteString("// Reduce answers the fact this row publishes from the one exact cell it read.\n")
	out.WriteString("// The read declares explicit sparsity, so an unwritten predecessor is delivered\n")
	out.WriteString("// as absence and settles as this rule's absent candidate: nothing here invents\n")
	out.WriteString("// a world the Factor never wrote.\n")
	fmt.Fprintf(out, "func (fold %s) Reduce(cell %s, present bool) (%s, %s.ReductionOutcome) {\n",
		reducerType, imports.typeName(read.axis.fact), imports.typeName(built.fold.results[0]), structure)
	out.WriteString("\tif !present {\n")
	fmt.Fprintf(out, "\t\tvar absent %s\n", imports.typeName(built.fold.results[0]))
	fmt.Fprintf(out, "\t\treturn absent, %s.NoCandidate\n", structure)
	out.WriteString("\t}\n")
	fmt.Fprintf(out, "\treturn %s\n}\n\n", call)
	return nil
}

// renderStructuralReduce emits the A form's Reduce: one branch ordinal in, one
// disposition out. There is no value to return because a structural
// publication writes no fact, which is exactly what its reducer declaring no
// output carrier means.
func renderStructuralReduce(out *strings.Builder, built *plan) error {
	imports := built.imports
	structure := imports.use(structurePackagePath)
	call, err := foldCall(built)
	if err != nil {
		return err
	}
	if len(built.fold.results) != 1 {
		return unexpressible(built.target.Spec.Key, "a structural fold that returns a value",
			"a structural publication writes no fact, so its reducer concludes a disposition and nothing else")
	}
	fmt.Fprintf(out, "func (fold %s) Reduce(branch uint64) %s.ReductionOutcome {\n", reducerType, structure)
	fmt.Fprintf(out, "\treturn %s\n}\n\n", call)
	fmt.Fprintf(out, "func (fold %s) Empty() %s.ReductionOutcome {\n", reducerType, structure)
	out.WriteString("\t// A trigger with no branch to settle instantiates nothing, which is a\n")
	out.WriteString("\t// concluded row and not a refusal.\n")
	fmt.Fprintf(out, "\treturn %s.NoSelection\n}\n\n", structure)
	return nil
}

func renderRouteReduce(out *strings.Builder, built *plan) error {
	imports := built.imports
	structure := imports.use(structurePackagePath)
	execution := imports.use(executionPackagePath)
	route := built.route.join
	position := -1
	for index, join := range built.fold.inputs {
		if join == route {
			position = index
		}
	}
	if position < 0 {
		return unexpressible(built.target.Spec.Key, "a routed output whose route join the fold does not consume",
			"the cell a route publishes at is the fold's own input")
	}
	if len(built.fold.results) != 2 {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("a routed fold answering %d results", len(built.fold.results)),
			"a routed fold publishes one fact and one disposition")
	}
	call, err := foldCall(built)
	if err != nil {
		return err
	}
	out.WriteString("// Reduce answers one selected route. The route coordinate, cell, and tag\n")
	out.WriteString("// are the three owner-issued halves of the one member the read observed,\n")
	out.WriteString("// so the fold never re-derives a destination or correlation.\n")
	fmt.Fprintf(out, "func (fold %s) Reduce(routeCoordinate %s, cell %s.SelectedCell[%s]) (%s, %s.ReductionOutcome) {\n",
		reducerType, imports.typeName(built.route.destinationType), execution, imports.typeName(route.axis.fact), imports.typeName(built.fold.results[0]), structure)
	fmt.Fprintf(out, "\treturn %s\n}\n\n", call)

	out.WriteString("// Empty settles the row whose derived relation selected no route at all. An\n")
	out.WriteString("// empty selection is not a refusal: it is the one disposition that says the\n")
	out.WriteString("// relation was read and named nothing.\n")
	fmt.Fprintf(out, "func (%s) Empty() %s.ReductionOutcome { return %s.NoSelection }\n\n", reducerType, structure, structure)
	return nil
}

func renderRow(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	out.WriteString("// " + rowType + " is the sealed static half of one plan row: the candidate its fold\n")
	out.WriteString("// is indexed by and every primitive the installer sealed through the plane.\n")
	fmt.Fprintf(out, "type %s struct {\n", rowType)
	fmt.Fprintf(out, "\tcandidate %s\n", imports.typeName(built.candidate.subject))
	for _, join := range built.joins {
		switch join.read.Form {
		case program.Exact:
			fmt.Fprintf(out, "\t%s %s.ExactRead[%s, %s]\n", join.name, execution,
				imports.typeName(join.axis.dense), imports.typeName(join.axis.fact))
			fmt.Fprintf(out, "\t%sPolicy %s.ReadCellPolicy[%s]\n", join.name, execution, imports.typeName(join.axis.fact))
		case program.Selected:
			fmt.Fprintf(out, "\t%s %s.SelectedRead[%s, %s]\n", join.name, execution,
				imports.typeName(join.axis.dense), imports.typeName(join.axis.fact))
		case program.Summary:
			if join.vectorSpan == nil {
				return unexpressible(built.target.Spec.Key, "a summary read over a Factor cursor",
					fmt.Sprintf("join %d spans a partition the emitted installer opens no vector cursor over", join.position))
			}
			// One sealed exact read per declared ordinal. The set's width is
			// the candidate's own census, so it is a row-local slice rather
			// than a family-wide constant.
			fmt.Fprintf(out, "\t%s []%s.ExactRead[%s, %s]\n", join.name, execution,
				imports.typeName(join.axis.dense), imports.typeName(join.axis.fact))
			fmt.Fprintf(out, "\t%sPolicy %s.ReadCellPolicy[%s]\n", join.name, execution, imports.typeName(join.axis.fact))
		default:
			return unexpressible(built.target.Spec.Key, fmt.Sprintf("a %s read", readFormName(join.read.Form)),
				fmt.Sprintf("join %d has no sealed read primitive in the emitted vocabulary", join.position))
		}
	}
	if built.shape == shapeStructural {
		// The census the issuance pass enumerated for this row. It is sealed
		// here, cold, because it is a property of the row and not of an
		// invocation: nothing counts a trigger's branches twice.
		out.WriteString("\tbranches int\n")
	}
	switch built.shape {
	case shapeCarry:
		fmt.Fprintf(out, "\twrite %s.CarryWrite[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
	case shapeExactFold, shapeSelectedExact:
		if built.carry != nil {
			fmt.Fprintf(out, "\twrite %s.CarryWrite[%s, %s]\n", execution,
				imports.typeName(built.write.dense), imports.typeName(built.write.fact))
			break
		}
		fmt.Fprintf(out, "\twrite %s.ExactWrite[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
	case shapeSelectedRoute:
		fmt.Fprintf(out, "\twrite %s.RouteWrite[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
	}
	out.WriteString("}\n\n")
	return nil
}

func renderFamily(out *strings.Builder, built *plan) {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	out.WriteString("// " + familyType + " is this rule's whole installed family: one row per plan row and\n")
	out.WriteString("// the sealed state every invocation reads. Nothing here is mutated after the\n")
	out.WriteString("// installer returns.\n")
	fmt.Fprintf(out, "type %s struct {\n", familyType)
	fmt.Fprintf(out, "\trows []%s\n", rowType)
	if built.fold.state != nil {
		fmt.Fprintf(out, "\tstate %s\n", imports.typeName(built.fold.state.state))
	}
	for _, axis := range built.familyAxes {
		fmt.Fprintf(out, "\t%s %s\n", axis.param, imports.typeName(axis.schemaType))
	}
	if built.shape == shapeSelectedRoute || built.shape == shapeSelectedExact {
		fmt.Fprintf(out, "\tplane %s.FormPlane[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
		out.WriteString("\twidth int\n")
	}
	for _, join := range vectorSpanJoins(built) {
		fmt.Fprintf(out, "\t%sWidth int\n", join.name)
	}
	out.WriteString("}\n\n")

	fmt.Fprintf(out, "func (sealed *%s) NewExecutor(run *%s.Run) %s.Executor {\n", familyType, execution, execution)
	out.WriteString("\tif sealed == nil || run == nil {\n\t\treturn nil\n\t}\n")
	for _, join := range vectorSpanJoins(built) {
		fmt.Fprintf(out, "\tif sealed.%sWidth < 0 {\n\t\treturn nil\n\t}\n", join.name)
	}
	if built.shape == shapeSelectedExact {
		out.WriteString("\tif sealed.width < 0 {\n\t\treturn nil\n\t}\n")
		out.WriteString("\t// Every buffer is sized once at the sealed width of the selection this rule\n")
		out.WriteString("\t// spans, so an ordinary invocation allocates nothing.\n")
		fmt.Fprintf(out, "\treturn &%s{\n", workerType)
		out.WriteString("\t\tfamily:  sealed,\n\t\trun:     run,\n")
		fmt.Fprintf(out, "\t\tmembers: make([]%s.RouteMember, sealed.width),\n", execution)
		fmt.Fprintf(out, "\t\tcells:   make([]%s.SelectedCell[%s], sealed.width),\n", execution, imports.typeName(built.selection.axis.fact))
		out.WriteString("\t}\n}\n\n")
	} else if built.shape == shapeSelectedRoute {
		out.WriteString("\tif sealed.width < 0 {\n\t\treturn nil\n\t}\n")
		out.WriteString("\t// Every buffer is sized once at the sealed width of the selection this rule\n")
		out.WriteString("\t// spans, so an ordinary invocation allocates nothing.\n")
		fmt.Fprintf(out, "\treturn &%s{\n", workerType)
		out.WriteString("\t\tfamily:  sealed,\n\t\trun:     run,\n")
		fmt.Fprintf(out, "\t\tmembers: make([]%s.RouteMember, sealed.width),\n", execution)
		fmt.Fprintf(out, "\t\tcells:   make([]%s.SelectedCell[%s], sealed.width),\n", execution, imports.typeName(built.write.fact))
		fmt.Fprintf(out, "\t\troutes:  make([]%s, sealed.width),\n", imports.typeName(built.route.destinationType))
		if built.route.carry != nil {
			fmt.Fprintf(out, "\t\tcarries: make([]%s.RouteCarry[%s], sealed.width),\n", execution, imports.typeName(built.write.fact))
		}
		for _, join := range vectorSpanJoins(built) {
			fmt.Fprintf(out, "\t\t%sCells: make([]%s.MemberCell[%s], sealed.%sWidth),\n",
				join.name, execution, imports.typeName(join.axis.fact), join.name)
		}
		out.WriteString("\t}\n}\n\n")
	} else if sets := vectorSpanJoins(built); len(sets) != 0 {
		// The member-set buffers are sized once at the widest set any row of
		// this rule declares, so a warm invocation over any row allocates
		// nothing.
		fmt.Fprintf(out, "\treturn &%s{\n", workerType)
		out.WriteString("\t\tfamily: sealed,\n\t\trun:    run,\n")
		for _, join := range sets {
			fmt.Fprintf(out, "\t\t%sCells: make([]%s.MemberCell[%s], sealed.%sWidth),\n",
				join.name, execution, imports.typeName(join.axis.fact), join.name)
		}
		out.WriteString("\t}\n}\n\n")
	} else {
		fmt.Fprintf(out, "\treturn &%s{family: sealed, run: run}\n}\n\n", workerType)
	}
	fmt.Fprintf(out, "func (*%s) InputCapacity() int  { return %d }\n", familyType, built.inputPorts)
	// A structural row publishes no Factor patch, so it claims no output slot
	// at all: its whole publication is the branch set it settles.
	outputs := len(built.target.Spec.Program.Fold.Outputs)
	if built.shape == shapeStructural {
		outputs = 0
	}
	fmt.Fprintf(out, "func (*%s) OutputCapacity() int { return %d }\n\n", familyType, outputs)
}

func renderWorker(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	out.WriteString("// " + workerType + " is one epoch's reusable invocation lane. Every scratch lives for\n")
	out.WriteString("// the worker's lifetime, so a warm invocation opens its cursors and its write\n")
	out.WriteString("// transaction without allocating.\n")
	fmt.Fprintf(out, "type %s struct {\n", workerType)
	fmt.Fprintf(out, "\tfamily *%s\n", familyType)
	fmt.Fprintf(out, "\trun    *%s.Run\n", execution)
	for _, join := range built.joins {
		switch join.read.Form {
		case program.Exact:
			fmt.Fprintf(out, "\t%s %s.Scratch[%s, %s]\n", join.name, execution,
				imports.typeName(join.axis.dense), imports.typeName(join.axis.fact))
		case program.Selected:
			fmt.Fprintf(out, "\t%s %s.SelectedScratch[%s, %s]\n", join.name, execution,
				imports.typeName(join.axis.dense), imports.typeName(join.axis.fact))
		case program.Summary:
			// One scratch lane serves every ordinal of the set: the members are
			// read in declaration order and the lane is returned to service
			// between them, so the vector costs one cursor rather than one per
			// member.
			fmt.Fprintf(out, "\t%s %s.Scratch[%s, %s]\n", join.name, execution,
				imports.typeName(join.axis.dense), imports.typeName(join.axis.fact))
			fmt.Fprintf(out, "\t%sCells []%s.MemberCell[%s]\n", join.name, execution, imports.typeName(join.axis.fact))
		}
	}
	switch built.shape {
	case shapeCarry:
		fmt.Fprintf(out, "\twrite %s.Scratch[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
	case shapeExactFold:
		// One extender per declared read. The chain is allocated once with the
		// worker, so a warm invocation refines the canonical product without
		// allocating a cell, region, or tuple buffer of its own.
		productPackage := imports.use(productPackagePath)
		for index, join := range built.joins {
			fmt.Fprintf(out, "\t%s %s.Extender[%s, %s, %s]\n", exactProductName(join), productPackage,
				imports.typeName(join.axis.dense), imports.typeName(join.axis.fact), exactTupleName(built, index-1))
		}
		fmt.Fprintf(out, "\twrite %s.Scratch[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
	case shapeSelectedExact:
		fmt.Fprintf(out, "\twrite %s.Scratch[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
		fmt.Fprintf(out, "\tmembers []%s.RouteMember\n", execution)
		fmt.Fprintf(out, "\tcells   []%s.SelectedCell[%s]\n", execution, imports.typeName(built.selection.axis.fact))
	case shapeSelectedRoute:
		fmt.Fprintf(out, "\twrite %s.RouteScratch[%s, %s]\n", execution,
			imports.typeName(built.write.dense), imports.typeName(built.write.fact))
		fmt.Fprintf(out, "\tmembers []%s.RouteMember\n", execution)
		fmt.Fprintf(out, "\tcells   []%s.SelectedCell[%s]\n", execution, imports.typeName(built.write.fact))
		fmt.Fprintf(out, "\troutes  []%s\n", imports.typeName(built.route.destinationType))
		if built.route.carry != nil {
			fmt.Fprintf(out, "\tcarries []%s.RouteCarry[%s]\n", execution, imports.typeName(built.write.fact))
		}
	}
	out.WriteString("}\n\n")

	out.WriteString("// settle submits one non-publishing disposition. Every refusal path in this\n")
	out.WriteString("// worker ends here, so the ticket is settled exactly once.\n")
	fmt.Fprintf(out, "func (lane *%s) settle(ticket %s.Ticket, outcome %s.ReductionOutcome) (%s.Result, bool) {\n",
		workerType, execution, structure, execution)
	fmt.Fprintf(out, "\tif !ticket.Submit(outcome) {\n\t\treturn %s.Result{}, false\n\t}\n", execution)
	fmt.Fprintf(out, "\treturn %s.NewResult(outcome, 0)\n}\n\n", execution)

	switch built.shape {
	case shapeCarry:
		if len(built.joins) == 0 {
			return renderSourceCarryExecute(out, built)
		}
		return renderCarryExecute(out, built)
	case shapeExactFold:
		return renderExactExecute(out, built)
	case shapeSelectedExact:
		return renderSelectedExactExecute(out, built)
	case shapeSelectedRoute:
		return renderRouteExecute(out, built)
	case shapeStructural:
		return renderStructuralExecute(out, built)
	}
	return nil
}

// renderStructuralExecute writes the A form's invocation: the prerequisite
// reads are taken, the cold branch set the trigger declares is delivered one
// member at a time, and the fold settles each branch in turn.
//
// Nothing is published at a coordinate. What the row publishes is the ordinals
// of the branches that activated, and the mounted member each ordinal stands
// for was resolved cold by the engine that mounted it.
func renderStructuralExecute(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)

	invocation := map[string]string{}
	for _, join := range built.joins {
		switch join.read.Form {
		case program.Exact:
			invocation[fmt.Sprintf("input%d", join.position)] = fmt.Sprintf("input%d", join.position)
		case program.Summary:
			invocation[fmt.Sprintf("input%d", join.position)] = fmt.Sprintf("%sVector", join.name)
		}
	}

	out.WriteString("// Execute settles one trigger's candidate branches: the declared reads are\n")
	out.WriteString("// taken, and every branch of the set the issuance pass enumerated for this row\n")
	out.WriteString("// is settled in turn. A branch is addressed by its ordinal and read at no\n")
	out.WriteString("// coordinate, so the census is the whole of what this worker is handed about\n")
	out.WriteString("// the set.\n")
	renderExecutePrologue(out, built)

	for _, join := range built.joins {
		switch join.read.Form {
		case program.Exact:
			fmt.Fprintf(out, "\tvar input%d %s\n", join.position, imports.typeName(join.axis.fact))
			fmt.Fprintf(out, "\tswitch lane.%sCell(row.%s, row.%sPolicy, ticket, &input%d) {\n", join.name, join.name, join.name, join.position)
			fmt.Fprintf(out, "\tcase %s.NoCandidate:\n\t\treturn lane.settle(ticket, %s.NoCandidate)\n", structure, structure)
			fmt.Fprintf(out, "\tcase %s.Refuse:\n\t\treturn lane.settle(ticket, %s.Refuse)\n", structure, structure)
			out.WriteString("\t}\n")
		case program.Summary:
			renderMemberVector(out, built, join)
		default:
			return unexpressible(built.target.Spec.Key, fmt.Sprintf("a %s read beside a structural output", readFormName(join.read.Form)),
				fmt.Sprintf("join %d is not a prerequisite the emitted worker delivers", join.position))
		}
	}

	out.WriteString("\t// The census is the engine's own: it enumerated this trigger's branch set\n")
	out.WriteString("\t// once, at issuance, and the installer sealed it onto this row. Nothing\n")
	out.WriteString("\t// here counts again.\n")
	fmt.Fprintf(out, "\toutcome := %s.FoldBranchSet(lane.run, &ticket, row.branches, %s{%s})\n",
		execution, reducerType, strings.Join(reducerLiteralFields(built, invocation), ", "))
	fmt.Fprintf(out, "\tif !ticket.Submit(outcome) {\n\t\treturn %s.Result{}, false\n\t}\n", execution)
	out.WriteString("\t// A structural row concludes no fact, so its Concrete disposition carries no\n")
	out.WriteString("\t// value slot at all.\n")
	fmt.Fprintf(out, "\treturn %s.NewResult(outcome, 0)\n}\n\n", execution)

	for _, join := range built.joins {
		switch join.read.Form {
		case program.Exact:
			if err := renderExactCell(out, built, join); err != nil {
				return err
			}
		case program.Summary:
			renderMemberCell(out, built, join)
		}
	}
	return nil
}

func renderExactExecute(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	productPackage := imports.use(productPackagePath)
	// The product is refined by the exact reads; the last of THEM names the
	// rows the fold drains. A spanned join refines nothing - it delivers one
	// vector per invocation - so it is not the tail even when it is declared
	// last.
	var last *joinPlan
	for _, join := range built.joins {
		if join.vectorSpan == nil {
			last = join
		}
	}
	if last == nil {
		return unexpressible(built.target.Spec.Key, "an exact fold refined by no exact read",
			"the canonical product is refined by exact cells, and a declaration whose reads are all vectors names no product to drain")
	}
	out.WriteString("// Execute drains the canonical product its declared exact reads refine, applies\n")
	out.WriteString("// the typed fold once per cell, and stages every concrete result into the one\n")
	out.WriteString("// write transaction the row publishes through. A cell publishes under the\n")
	out.WriteString("// region the reads it was derived from reported, so nothing here claims support\n")
	out.WriteString("// the product did not prove.\n")
	renderExecutePrologue(out, built)
	fmt.Fprintf(out, "\tseed, seedStatus, seedOK := %s.NewSeed(ticket)\n", productPackage)
	fmt.Fprintf(out, "\tif !seedOK || seedStatus == %s.RefineRefuse {\n\t\treturn %s.Result{}, false\n\t}\n", productPackage, execution)
	out.WriteString("\t// Empty support is an authenticated absent candidate, never a refusal.\n")
	fmt.Fprintf(out, "\tif seedStatus == %s.RefineEmpty {\n\t\treturn lane.settle(ticket, %s.NoCandidate)\n\t}\n", productPackage, structure)
	// A spanned join is read ONCE per invocation, not once per product cell:
	// its span is the denominator the declaration named, and the cells that
	// fill it are the same for every refinement of the exact product. What it
	// contributes to a cell is the conjunction of its own cells' supports,
	// taken below where the product's region is known.
	for _, join := range vectorSpanJoins(built) {
		fmt.Fprintf(out, "\t%sCount := len(row.%s)\n", join.name, join.name)
		fmt.Fprintf(out, "\tif %sCount > len(lane.%sCells) {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", join.name, join.name, structure)
		fmt.Fprintf(out, "\t%sCells := lane.%sCells[:%sCount]\n", join.name, join.name, join.name)
		fmt.Fprintf(out, "\tfor index := 0; index < %sCount; index++ {\n", join.name)
		fmt.Fprintf(out, "\t\tif lane.%sCell(row.%s[index], row.%sPolicy, ticket, &%sCells[index]) != %s.Concrete {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n",
			join.name, join.name, join.name, join.name, structure, structure)
		out.WriteString("\t}\n")
		fmt.Fprintf(out, "\t%sVector, %sVectorOK := %s.NewMemberVector(%sCells)\n", join.name, join.name, execution, join.name)
		fmt.Fprintf(out, "\tif !%sVectorOK {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", join.name, structure)
	}
	input := "seed.Rows()"
	for _, join := range built.joins {
		if join.vectorSpan != nil {
			continue
		}
		rows := fmt.Sprintf("rows%d", join.position)
		fmt.Fprintf(out, "\t%s, status%d, status%dOK := lane.%s.Extend(ticket, %s, row.%s, &lane.%s)\n",
			rows, join.position, join.position, exactProductName(join), input, join.name, join.name)
		fmt.Fprintf(out, "\tif !status%dOK || status%d != %s.RefineAvailable {\n\t\treturn %s.Result{}, false\n\t}\n",
			join.position, join.position, productPackage, execution)
		input = rows
	}
	fmt.Fprintf(out, "\tstaged := 0\n\tfor index := 0; index < rows%d.Count(); index++ {\n", last.position)
	fmt.Fprintf(out, "\t\tif !ticket.Checkpoint() {\n\t\t\t_ = lane.write.Discard(ticket)\n\t\t\treturn %s.Result{}, false\n\t\t}\n", execution)
	fmt.Fprintf(out, "\t\tregion, tuple, tupleOK := rows%d.At(index)\n", last.position)
	fmt.Fprintf(out, "\t\tif !tupleOK || !region.Valid() {\n\t\t\t_ = lane.write.Discard(ticket)\n\t\t\treturn %s.Result{}, false\n\t\t}\n", execution)
	for _, join := range vectorSpanJoins(built) {
		// A conclusion holds only where every read it consumed holds, so the
		// cell's region narrows to the conjunction with every cell of the
		// vector. Supports neither of which contains the other are refused
		// there by name rather than resolved by arrival order.
		fmt.Fprintf(out, "\t\tregion, regionOK := %s.ConjoinCells(region, %sCells)\n", execution, join.name)
		fmt.Fprintf(out, "\t\tif !regionOK {\n\t\t\t_ = lane.write.Discard(ticket)\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
		fmt.Fprintf(out, "\t\t_ = region\n")
	}
	present := make([]string, 0, len(built.joins))
	for _, join := range built.joins {
		// A vector's cells carry their own presence, one per coordinate of the
		// span, and the fold is what decides what an absent operand means.
		// Only the exact cells gate the row.
		if join.vectorSpan != nil {
			continue
		}
		cell := exactCellExpression(built, join)
		fmt.Fprintf(out, "\t\t%s, present%d := row.%sPolicy.Cell(%s.Value(), %s.Present())\n",
			exactCellName(join), join.position, join.name, cell, cell)
		present = append(present, fmt.Sprintf("!present%d", join.position))
	}
	out.WriteString("\t\t// A cell whose declared reads are not all present is this rule's absent\n")
	out.WriteString("\t\t// candidate over exactly that region, and contributes no patch.\n")
	fmt.Fprintf(out, "\t\tif %s {\n\t\t\tcontinue\n\t\t}\n", strings.Join(present, " || "))
	arguments := make([]string, 0, len(built.fold.inputs))
	for _, join := range built.fold.inputs {
		if join.vectorSpan != nil {
			arguments = append(arguments, join.name+"Vector")
			continue
		}
		arguments = append(arguments, exactCellName(join))
	}
	for _, join := range built.joins {
		if join.vectorSpan != nil {
			continue
		}
		if _, consumed := foldInputPosition(built, join); !consumed {
			fmt.Fprintf(out, "\t\t_ = %s\n", exactCellName(join))
		}
	}
	fmt.Fprintf(out, "\t\tvalue, outcome := (%s{%s}).Reduce(%s)\n",
		reducerType, strings.Join(reducerLiteralFields(built, nil), ", "), strings.Join(arguments, ", "))
	fmt.Fprintf(out, "\t\tswitch outcome {\n\t\tcase %s.Concrete:\n", structure)
	if built.carry != nil {
		// Every carried coordinate passes through the candidate's transition
		// in the same patch the reduced fact is staged in, so the row's whole
		// publication - what it concluded and what it retained - lands
		// atomically or not at all.
		fmt.Fprintf(out, "\t\t\tif !row.write.Carry(ticket, &lane.write, region) {\n\t\t\t\t_ = lane.write.Discard(ticket)\n\t\t\t\treturn %s.Result{}, false\n\t\t\t}\n", execution)
	}
	fmt.Fprintf(out, "\t\t\tif !row.write.Stage(ticket, &lane.write, region, value) {\n\t\t\t\t_ = lane.write.Discard(ticket)\n\t\t\t\treturn %s.Result{}, false\n\t\t\t}\n", execution)
	out.WriteString("\t\t\tstaged++\n")
	fmt.Fprintf(out, "\t\tcase %s.NoCandidate:\n", structure)
	out.WriteString("\t\t\t// The declared absent successor publishes nothing for this cell.\n")
	out.WriteString("\t\tdefault:\n")
	out.WriteString("\t\t\t_ = lane.write.Discard(ticket)\n\t\t\treturn lane.settle(ticket, outcome)\n")
	out.WriteString("\t\t}\n\t}\n")
	fmt.Fprintf(out, "\tif staged == 0 {\n\t\treturn lane.settle(ticket, %s.NoCandidate)\n\t}\n", structure)
	fmt.Fprintf(out, "\tif !row.write.Close(ticket, &lane.write) {\n\t\t_ = lane.write.Discard(ticket)\n\t\treturn %s.Result{}, false\n\t}\n", execution)
	out.WriteString("\t// One accepted patch is one concrete result, however many cells it holds.\n")
	fmt.Fprintf(out, "\tif !ticket.Submit(%s.Concrete) {\n\t\treturn %s.Result{}, false\n\t}\n", structure, execution)
	fmt.Fprintf(out, "\treturn %s.NewResult(%s.Concrete, 1)\n}\n\n", execution, structure)
	// A spanned join reads its cells through the same cursor discipline every
	// member set is read under, whichever form delivers them.
	for _, join := range vectorSpanJoins(built) {
		renderMemberCell(out, built, join)
	}
	return nil
}

// foldInputPosition answers the fold input position one declared read is
// consumed at. A read the fold does not consume is still drained: it is a
// declared prerequisite of the product, and its absence still refines away the
// cells this rule has no evidence over.
func foldInputPosition(built *plan, join *joinPlan) (int, bool) {
	for position, input := range built.fold.inputs {
		if input == join {
			return position, true
		}
	}
	return 0, false
}

func renderExecutePrologue(out *strings.Builder, built *plan) {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	fmt.Fprintf(out, "func (lane *%s) Execute(frame %s.Frame, ticket %s.Ticket) (%s.Result, bool) {\n",
		workerType, execution, execution, execution)
	fmt.Fprintf(out, "\tif lane == nil || lane.family == nil || lane.run == nil || !frame.Valid(ticket) || !lane.run.Owns(ticket) {\n\t\treturn %s.Result{}, false\n\t}\n", execution)
	out.WriteString("\tlocal, localOK := ticket.LocalOrdinal()\n")
	fmt.Fprintf(out, "\tif !localOK || uint64(local) >= uint64(len(lane.family.rows)) {\n\t\treturn %s.Result{}, false\n\t}\n", execution)
	out.WriteString("\trow := lane.family.rows[local]\n")
}

func renderExecuteEpilogue(out *strings.Builder, built *plan) {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	fmt.Fprintf(out, "\tif !ticket.Submit(outcome) {\n\t\treturn %s.Result{}, false\n\t}\n", execution)
	out.WriteString("\twritten := 0\n")
	fmt.Fprintf(out, "\tif outcome == %s.Concrete {\n\t\twritten = 1\n\t}\n", structure)
	fmt.Fprintf(out, "\treturn %s.NewResult(outcome, written)\n}\n\n", execution)
}

// renderSourceCarryReduce writes the judgment of a carry that reads nothing.
// The candidate is the whole of its input, so Reduce takes no cell: a rule of
// this shape answers from the directory row it is indexed by and from whatever
// cold state its family was sealed with.
func renderSourceCarryReduce(out *strings.Builder, built *plan) error {
	imports := built.imports
	structure := imports.use(structurePackagePath)
	if len(built.fold.inputs) != 0 {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("a read-free carry folding %d inputs", len(built.fold.inputs)),
			"a fold with no declared read has no cell to consume, so its reducer takes the candidate alone")
	}
	if len(built.fold.results) != 2 {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("a carry fold answering %d results", len(built.fold.results)),
			"a carry fold publishes one fact and one disposition")
	}
	call, err := foldCall(built)
	if err != nil {
		return err
	}
	out.WriteString("// Reduce answers the fact this row publishes from its candidate alone. The\n")
	out.WriteString("// declaration names no read, so there is no cell here and no absence to\n")
	out.WriteString("// interpret: the whole of this judgment is the directory row the invocation\n")
	out.WriteString("// is indexed by.\n")
	fmt.Fprintf(out, "func (fold %s) Reduce() (%s, %s.ReductionOutcome) {\n",
		reducerType, imports.typeName(built.fold.results[0]), structure)
	fmt.Fprintf(out, "\treturn %s\n}\n\n", call)
	return nil
}

// renderSourceCarryExecute writes the invocation of a carry that reads nothing.
// It opens no cursor, so the publication holds over the invocation's own
// authenticated support - the honest region for a judgment that is a function
// of the candidate, and the one FoldSourceCarry publishes under.
func renderSourceCarryExecute(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	out.WriteString("// Execute performs one read-free carry invocation: the candidate's judgment is\n")
	out.WriteString("// taken, and every carried coordinate passes through the candidate's transition\n")
	out.WriteString("// in the same patch the row publishes through.\n")
	renderExecutePrologue(out, built)
	fmt.Fprintf(out, "\toutcome := %s.FoldSourceCarry(ticket, %s{%s}, row.write, &lane.write)\n",
		execution, reducerType, strings.Join(reducerLiteralFields(built, nil), ", "))
	renderExecuteEpilogue(out, built)
	return nil
}

func renderCarryExecute(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	read := built.joins[0]
	out.WriteString("// Execute performs one carry invocation: the declared exact cell is reduced to\n")
	out.WriteString("// the fact this row publishes, and every carried coordinate passes through the\n")
	out.WriteString("// candidate's transition in the same patch.\n")
	renderExecutePrologue(out, built)
	fmt.Fprintf(out, "\toutcome := %s.FoldCarry(ticket, %s{%s}, row.%s, &lane.%s, row.write, &lane.write)\n",
		execution, reducerType, strings.Join(reducerLiteralFields(built, nil), ", "), read.name, read.name)
	renderExecuteEpilogue(out, built)
	return nil
}

// reducerLiteralFields spells the reducer literal the worker constructs, in
// the field order the type declares. Values supplied by the invocation are
// named by the caller; every other field takes the row's sealed carrier.
func reducerLiteralFields(built *plan, invocation map[string]string) []string {
	fields := reducerFields(built)
	spelled := make([]string, 0, len(fields)+1)
	if built.fold.state != nil {
		spelled = append(spelled, "state: lane.family.state")
	}
	for _, field := range fields {
		value := "row." + field
		if invocation != nil {
			if supplied, present := invocation[field]; present {
				value = supplied
			}
		}
		spelled = append(spelled, field+": "+value)
	}
	return spelled
}

func renderRouteExecute(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	route := built.route.join
	derivation := route.derivation

	invocation := map[string]string{}
	for _, join := range built.joins {
		if join == route {
			continue
		}
		switch join.read.Form {
		case program.Exact:
			invocation[fmt.Sprintf("input%d", join.position)] = fmt.Sprintf("input%d", join.position)
		case program.Summary:
			invocation[fmt.Sprintf("input%d", join.position)] = fmt.Sprintf("%sVector", join.name)
		}
	}

	out.WriteString("// Execute performs one routed invocation: the prerequisite reads are taken,\n")
	out.WriteString("// the declared relation derives this candidate's route set once, the selection\n")
	out.WriteString("// is observed at exactly those members, and one fold publishes at each.\n")
	renderExecutePrologue(out, built)

	for _, join := range built.joins {
		if join == route {
			continue
		}
		switch join.read.Form {
		case program.Exact:
			fmt.Fprintf(out, "\tvar input%d %s\n", join.position, imports.typeName(join.axis.fact))
			fmt.Fprintf(out, "\tswitch lane.%sCell(row.%s, row.%sPolicy, ticket, &input%d) {\n", join.name, join.name, join.name, join.position)
			fmt.Fprintf(out, "\tcase %s.NoCandidate:\n\t\treturn lane.settle(ticket, %s.NoCandidate)\n", structure, structure)
			fmt.Fprintf(out, "\tcase %s.Refuse:\n\t\treturn lane.settle(ticket, %s.Refuse)\n", structure, structure)
			out.WriteString("\t}\n")
		case program.Summary:
			renderMemberVector(out, built, join)
		default:
			return unexpressible(built.target.Spec.Key, fmt.Sprintf("a %s prerequisite of a routed output", readFormName(join.read.Form)),
				fmt.Sprintf("join %d is neither the route join nor a prerequisite the emitted worker delivers", join.position))
		}
	}

	arguments := make([]string, 0, len(derivation.staticAxes)+len(derivation.arguments))
	for _, axis := range derivation.staticAxes {
		arguments = append(arguments, "lane.family."+axis.param)
	}
	for _, argument := range derivation.arguments {
		switch {
		case argument.candidate:
			arguments = append(arguments, "row.candidate")
		case argument.many:
			if argument.join == nil || argument.join.vectorSpan == nil || argument.form != member.ReadFormSummary {
				return unexpressible(built.target.Spec.Key, "a relation derivation over a whole selection",
					fmt.Sprintf("relation %q consumes the cells of join %d, and only a whole-vector read has an emitted delivery", route.relation.Name, argument.join.position))
			}
			arguments = append(arguments, fmt.Sprintf("%sVector", argument.join.name))
		default:
			arguments = append(arguments, fmt.Sprintf("input%d", argument.join.position))
		}
	}
	out.WriteString("\t// The route set is the relation's own answer, derived once per invocation from\n")
	out.WriteString("\t// the carriers its declaration names. Nothing below re-derives it.\n")
	fmt.Fprintf(out, "\tderived, derivedOK := %s\n", imports.call(derivation.build, "", arguments...))
	fmt.Fprintf(out, "\tif !derivedOK {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", structure)
	fmt.Fprintf(out, "\tcount := %s\n", imports.call(derivation.count, "", "derived"))
	carryFence := ""
	if built.route.carry != nil {
		carryFence = " || count > len(lane.carries)"
	}
	fmt.Fprintf(out, "\tif count < 0 || count > len(lane.members) || count > len(lane.cells) || count > len(lane.routes)%s {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", carryFence, structure)
	out.WriteString("\tmembers := lane.members[:count]\n\tcells := lane.cells[:count]\n\troutes := lane.routes[:count]\n")
	if built.route.carry != nil {
		out.WriteString("\tcarries := lane.carries[:count]\n")
	}
	out.WriteString("\tfor index := 0; index < count; index++ {\n")
	fmt.Fprintf(out, "\t\tselected, selectedOK := %s\n", imports.call(derivation.at, "", "derived", "index"))
	fmt.Fprintf(out, "\t\tif !selectedOK {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
	keyExpression, err := projectionExpression(built, route.key, "selected", "\t\t", out)
	if err != nil {
		return err
	}
	tagExpression, err := projectionExpression(built, route.predicate, "selected", "\t\t", out)
	if err != nil {
		return err
	}
	destinationExpression, err := projectionExpression(built, built.route.destination, "selected", "\t\t", out)
	if err != nil {
		return err
	}
	if route.key.Result != route.axis.source.Binding.Key.Carrier {
		return unexpressible(built.target.Spec.Key, "a route key that is not the axis's own key carrier",
			fmt.Sprintf("projection %q publishes %s", route.key.Name, route.key.Result))
	}
	fmt.Fprintf(out, "\t\tdense, denseOK := %s\n", imports.call(route.axis.normalizer, "lane.family."+route.axis.param, keyExpression))
	fmt.Fprintf(out, "\t\tif !denseOK {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
	fmt.Fprintf(out, "\t\tdestinationDense, destinationDenseOK := %s\n", imports.call(route.axis.normalizer, "lane.family."+route.axis.param, destinationExpression))
	fmt.Fprintf(out, "\t\tif !destinationDenseOK {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
	fmt.Fprintf(out, "\t\tmember, memberOK := lane.family.plane.RouteMember(uint32(dense), uint32(destinationDense), uint64(%s))\n", tagExpression)
	fmt.Fprintf(out, "\t\tif !memberOK {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
	out.WriteString("\t\tmembers[index] = member\n")
	fmt.Fprintf(out, "\t\troutes[index] = %s\n", destinationExpression)
	if built.route.carry != nil {
		// One closure per published row, taken over the row the relation
		// answered. It is a method value on that row, so the family holds no
		// function field and the transition is the row's own.
		fmt.Fprintf(out, "\t\tcarries[index] = %s\n", imports.methodValue(built.route.carry.Implementation, "selected"))
	}
	out.WriteString("\t}\n")

	out.WriteString("\t// An empty derived relation is a read that named nothing, which is exhausted\n")
	out.WriteString("\t// rather than available; anything else is a selection that did not observe.\n")
	fmt.Fprintf(out, "\tstatus := row.%s.Observe(ticket, &lane.%s, members, cells)\n", route.name, route.name)
	out.WriteString("\tif count == 0 {\n")
	fmt.Fprintf(out, "\t\tif status != %s.ReadExhausted {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", execution, structure)
	fmt.Fprintf(out, "\t} else if status != %s.ReadAvailable {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", execution, structure)
	if built.route.carry != nil {
		fmt.Fprintf(out, "\toutcome := %s.FoldSelectedRouteCarry(ticket, row.write, &lane.write, cells, members, routes, carries, %s{%s})\n",
			execution, reducerType, strings.Join(reducerLiteralFields(built, invocation), ", "))
	} else {
		fmt.Fprintf(out, "\toutcome := %s.FoldSelectedRoute(ticket, row.write, &lane.write, cells, members, routes, %s{%s})\n",
			execution, reducerType, strings.Join(reducerLiteralFields(built, invocation), ", "))
	}
	renderExecuteEpilogue(out, built)

	for _, join := range built.joins {
		if join == route {
			continue
		}
		switch join.read.Form {
		case program.Exact:
			if err := renderExactCell(out, built, join); err != nil {
				return err
			}
		case program.Summary:
			renderMemberCell(out, built, join)
		}
	}
	return nil
}

// vectorSpanJoins is the declaration's ordered member-set reads: the joins whose
// relation is a self-provided nested member set, and whose Summary read is
// therefore delivered as one vector per invocation.
func vectorSpanJoins(built *plan) []*joinPlan {
	joins := make([]*joinPlan, 0, len(built.joins))
	for _, join := range built.joins {
		if join.vectorSpan != nil {
			joins = append(joins, join)
		}
	}
	return joins
}

// renderMemberVector emits one invocation's delivery of a nested member set:
// every declared ordinal is read at its own sealed coordinate into the lane's
// cell buffer, and the filled buffer is viewed as the vector its reader is
// declared to receive. Absence is carried per cell, so an unwritten member
// stays the cell its owner declared at that ordinal.
func renderMemberVector(out *strings.Builder, built *plan, join *joinPlan) {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	fmt.Fprintf(out, "\t%sCount := len(row.%s)\n", join.name, join.name)
	fmt.Fprintf(out, "\tif %sCount > len(lane.%sCells) {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n",
		join.name, join.name, structure)
	fmt.Fprintf(out, "\t%sCells := lane.%sCells[:%sCount]\n", join.name, join.name, join.name)
	fmt.Fprintf(out, "\tfor index := 0; index < %sCount; index++ {\n", join.name)
	fmt.Fprintf(out, "\t\tif lane.%sCell(row.%s[index], row.%sPolicy, ticket, &%sCells[index]) != %s.Concrete {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n",
		join.name, join.name, join.name, join.name, structure, structure)
	out.WriteString("\t}\n")
	fmt.Fprintf(out, "\t%sVector, %sVectorOK := %s.NewMemberVector(%sCells)\n", join.name, join.name, execution, join.name)
	fmt.Fprintf(out, "\tif !%sVectorOK {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", join.name, structure)
}

// renderMemberCell emits the cursor discipline one member of a nested set is
// read under: open, take the cell, close, and return the lane to service so the
// next ordinal opens on it. A member coordinate the plane never declared is not
// an absence - it is a census disagreeing with the Factor - so it refuses
// rather than settling as an absent candidate.
func renderMemberCell(out *strings.Builder, built *plan, join *joinPlan) {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	fmt.Fprintf(out, "// %sCell takes one member of a nested set at its own sealed coordinate.\n", join.name)
	fmt.Fprintf(out, "func (lane *%s) %sCell(read %s.ExactRead[%s, %s], policy %s.ReadCellPolicy[%s], ticket %s.Ticket, destination *%s.MemberCell[%s]) %s.ReductionOutcome {\n",
		workerType, join.name, execution, imports.typeName(join.axis.dense), imports.typeName(join.axis.fact),
		execution, imports.typeName(join.axis.fact),
		execution, execution, imports.typeName(join.axis.fact), structure)
	fmt.Fprintf(out, "\tif lane == nil || destination == nil || !read.Valid() {\n\t\treturn %s.Refuse\n\t}\n", structure)
	fmt.Fprintf(out, "\tif read.Read(ticket, &lane.%s) != %s.ReadAvailable {\n\t\t_ = lane.%s.Discard(ticket)\n\t\treturn %s.Refuse\n\t}\n",
		join.name, execution, join.name, structure)
	fmt.Fprintf(out, "\tcell, available := lane.%s.Value()\n", join.name)
	fmt.Fprintf(out, "\tpresent := lane.%s.Present()\n", join.name)
	// The support this member was observed over travels with it. A vector's
	// cells are read one coordinate at a time and each answers over what its
	// own read proved, so the conclusion folded from them holds over the
	// conjunction of their supports - which the fold cannot take if the cell
	// arrives without one.
	fmt.Fprintf(out, "\tregion, regionOK := lane.%s.Region()\n", join.name)
	fmt.Fprintf(out, "\tif !read.Close(ticket, &lane.%s) || !lane.%s.Reuse(ticket) {\n\t\t_ = lane.%s.Discard(ticket)\n\t\treturn %s.Refuse\n\t}\n",
		join.name, join.name, join.name, structure)
	fmt.Fprintf(out, "\tif !available || !regionOK {\n\t\treturn %s.Refuse\n\t}\n", structure)
	out.WriteString("\tcell, present = policy.Cell(cell, present)\n")
	fmt.Fprintf(out, "\t*destination = %s.MemberCell[%s]{Value: cell, Present: present, Region: region}\n", execution, imports.typeName(join.axis.fact))
	fmt.Fprintf(out, "\treturn %s.Concrete\n}\n\n", structure)
}

// projectionExpression emits the destructuring of one owner projection
// accessor and answers the expression its declared result index names. The
// result convention is the owner's: a sole-result accessor binds one name, a
// paired one binds both and the index selects.
func projectionExpression(built *plan, projection definition.Projection, receiver, indent string, out *strings.Builder) (string, error) {
	return projectionExpressionRefusing(built, projection, receiver, indent,
		"return lane.settle(ticket, "+built.imports.use(structurePackagePath)+".Refuse)", out)
}

// projectionExpressionRefusing is projectionExpression under a caller-supplied
// refusal. The destructuring is the owner's convention either way; only the
// statement a failed projection returns through belongs to the surface it is
// emitted into.
func projectionExpressionRefusing(built *plan, projection definition.Projection, receiver, indent, refusal string, out *strings.Builder) (string, error) {
	imports := built.imports
	call := imports.call(projection.Accessor, receiver)
	prefix := strings.ToLower(projection.Name[:1]) + projection.Name[1:]
	switch projection.Accessor.ResultIndex {
	case -1:
		fmt.Fprintf(out, "%s%s, %sOK := %s\n", indent, prefix, prefix, call)
		fmt.Fprintf(out, "%sif !%sOK {\n%s\t%s\n%s}\n", indent, prefix, indent, refusal, indent)
		return prefix, nil
	case 0:
		fmt.Fprintf(out, "%s%s, %sPaired, %sOK := %s\n", indent, prefix, prefix, prefix, call)
		fmt.Fprintf(out, "%s_ = %sPaired\n", indent, prefix)
	case 1:
		fmt.Fprintf(out, "%s%sPaired, %s, %sOK := %s\n", indent, prefix, prefix, prefix, call)
		fmt.Fprintf(out, "%s_ = %sPaired\n", indent, prefix)
	default:
		return "", unexpressible(built.target.Spec.Key, "a projection accessor with an unreachable result index",
			fmt.Sprintf("projection %q names result %d", projection.Name, projection.Accessor.ResultIndex))
	}
	fmt.Fprintf(out, "%sif !%sOK {\n%s\t%s\n%s}\n", indent, prefix, indent, refusal, indent)
	return prefix, nil
}

// renderExactCell emits the one cursor discipline an exact prerequisite read
// follows: open, close, and answer the cell under this read's own sealed
// materialization policy. An exact cursor delivers the observed coordinate
// unchanged and leaves the substitution to its caller, so the row's policy -
// derived by the execution layer from the declared contract and the Factor the
// read is sealed against - is what says whether an unwritten coordinate is this
// rule's absent candidate or the Factor's declared default.
func renderExactCell(out *strings.Builder, built *plan, join *joinPlan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	fmt.Fprintf(out, "// %sCell takes one exact prerequisite cell. The cursor is closed before the\n", join.name)
	out.WriteString("// value is used, and the row's sealed policy settles what an unwritten\n")
	out.WriteString("// coordinate delivers.\n")
	fmt.Fprintf(out, "func (lane *%s) %sCell(read %s.ExactRead[%s, %s], policy %s.ReadCellPolicy[%s], ticket %s.Ticket, destination *%s) %s.ReductionOutcome {\n",
		workerType, join.name, execution, imports.typeName(join.axis.dense), imports.typeName(join.axis.fact),
		execution, imports.typeName(join.axis.fact),
		execution, imports.typeName(join.axis.fact), structure)
	fmt.Fprintf(out, "\tif lane == nil || destination == nil || !read.Valid() {\n\t\treturn %s.Refuse\n\t}\n", structure)
	fmt.Fprintf(out, "\tswitch read.Read(ticket, &lane.%s) {\n", join.name)
	fmt.Fprintf(out, "\tcase %s.ReadAvailable:\n", execution)
	fmt.Fprintf(out, "\t\tcell, available := lane.%s.Value()\n", join.name)
	fmt.Fprintf(out, "\t\tpresent := lane.%s.Present()\n", join.name)
	fmt.Fprintf(out, "\t\tif !read.Close(ticket, &lane.%s) {\n\t\t\t_ = lane.%s.Discard(ticket)\n\t\t\treturn %s.Refuse\n\t\t}\n",
		join.name, join.name, structure)
	fmt.Fprintf(out, "\t\tif !available {\n\t\t\treturn %s.Refuse\n\t\t}\n", structure)
	fmt.Fprintf(out, "\t\tcell, present = policy.Cell(cell, present)\n")
	fmt.Fprintf(out, "\t\tif !present {\n\t\t\treturn %s.NoCandidate\n\t\t}\n", structure)
	out.WriteString("\t\t*destination = cell\n")
	fmt.Fprintf(out, "\t\treturn %s.Concrete\n", structure)
	fmt.Fprintf(out, "\tcase %s.ReadExhausted:\n", execution)
	fmt.Fprintf(out, "\t\tif !read.Close(ticket, &lane.%s) {\n\t\t\treturn %s.Refuse\n\t\t}\n", join.name, structure)
	fmt.Fprintf(out, "\t\treturn %s.NoCandidate\n", structure)
	out.WriteString("\tdefault:\n")
	fmt.Fprintf(out, "\t\t_ = lane.%s.Discard(ticket)\n\t\treturn %s.Refuse\n", join.name, structure)
	out.WriteString("\t}\n}\n\n")
	return nil
}

// exactProductName is the worker field one declared read's product extender is
// held under. It is keyed by the read's own declared position, so the chain a
// family builds is the declaration's read order and not a discovery order.
func exactProductName(join *joinPlan) string {
	return fmt.Sprintf("product%d", join.position)
}

// exactTupleName is the emitted alias of the product tuple after the read at
// index has been consed on. Index -1 is the seed's empty tuple, which the
// product package spells as the empty struct.
func exactTupleName(built *plan, index int) string {
	if index < 0 || index >= len(built.joins) {
		return "struct{}"
	}
	return fmt.Sprintf("productTuple%d", built.joins[index].position)
}

// renderExactTuples writes the typed product tuple aliases one exact fold's
// read chain constructs. They are aliases rather than defined types because
// the product package owns the shape; naming it here only keeps the extender
// and cursor declarations readable.
func renderExactTuples(out *strings.Builder, built *plan) {
	imports := built.imports
	productPackage := imports.use(productPackagePath)
	out.WriteString("// The typed product tuples this rule's read chain constructs. Each alias is\n")
	out.WriteString("// the tuple after one more declared read has been consed on, so the head is\n")
	out.WriteString("// always the newest read and the tail walks back to the first.\n")
	out.WriteString("type (\n")
	for index, join := range built.joins {
		fmt.Fprintf(out, "\t%s = %s.Cons[%s.Cell[%s], %s]\n", exactTupleName(built, index), productPackage,
			productPackage, imports.typeName(join.axis.fact), exactTupleName(built, index-1))
	}
	out.WriteString(")\n\n")
}

// exactCellExpression spells the product cell of one declared read inside a
// tuple of the whole chain. The extender conses the newest read at the head, so
// a read is reached by walking the tail back from the last one.
func exactCellExpression(built *plan, join *joinPlan) string {
	// The tuple holds one cell per join the PRODUCT refines, in declaration
	// order. A spanned join refines nothing - it is delivered once per
	// invocation - so it occupies no position here, and walking past it would
	// read every later cell at the wrong depth.
	product := make([]*joinPlan, 0, len(built.joins))
	for _, candidate := range built.joins {
		if candidate.vectorSpan == nil {
			product = append(product, candidate)
		}
	}
	expression := "tuple"
	for index := len(product) - 1; index > 0; index-- {
		if product[index] == join {
			break
		}
		expression += ".Tail()"
	}
	return expression + ".Head()"
}

// renderSelectedExactReduce writes the fold of a conclusion over a selection.
// The whole delivery is the one argument; every other declared read is sealed
// into the reducer as a field, because this row is called once and has no
// cadence to hand a prerequisite through.
func renderSelectedExactReduce(out *strings.Builder, built *plan) error {
	imports := built.imports
	structure := imports.use(structurePackagePath)
	if len(built.fold.results) != 2 {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("an exact conclusion answering %d results", len(built.fold.results)),
			"an exact conclusion publishes one fact and one disposition")
	}
	var delivery *definition.Argument
	for index := range built.fold.arguments {
		if built.fold.arguments[index].Role == definition.ArgumentVector {
			delivery = &built.fold.arguments[index]
		}
	}
	if delivery == nil || !delivery.Slice {
		return unexpressible(built.target.Spec.Key, "an exact conclusion over a delivery that is not a selection",
			"the fold of this form is handed the cells its selection observed, each paired with the tag it was correlated by")
	}
	call, err := foldCall(built)
	if err != nil {
		return err
	}
	out.WriteString("// Reduce is the one irreducible typed judgment of this family. It is called\n")
	out.WriteString("// ONCE per candidate and handed every member its selection observed, because\n")
	out.WriteString("// this row concludes one fact from all of them rather than one fact at each.\n")
	fmt.Fprintf(out, "func (fold %s) Reduce(cells []%s[%s]) (%s, %s.ReductionOutcome) {\n",
		reducerType, imports.typeName(delivery.Type), imports.typeName(delivery.Element),
		imports.typeName(built.fold.results[0]), structure)
	fmt.Fprintf(out, "\treturn %s\n}\n\n", call)
	return nil
}

// renderSelectedExactExecute writes the invocation of a conclusion over a
// selection: the exact prerequisite is taken, the declared relation derives
// this candidate's member set once, the selection is observed at exactly those
// members, and ONE fold concludes over the whole delivery.
//
// The prerequisite's read is inlined rather than taken through a helper
// because its support region has to stay in scope: the published fact holds
// over what the prerequisite AND every member proved, and the fold primitive
// derives that from the regions this worker hands it.
func renderSelectedExactExecute(out *strings.Builder, built *plan) error {
	imports := built.imports
	execution := imports.use(executionPackagePath)
	structure := imports.use(structurePackagePath)
	selection := built.selection
	derivation := selection.derivation
	prerequisite := built.joins[0]
	if prerequisite == selection {
		prerequisite = built.joins[1]
	}
	if prerequisite.read.Contract.Sparse != program.SparseExplicit {
		return unexpressible(built.target.Spec.Key, fmt.Sprintf("an exact prerequisite with %s sparsity", sparseName(prerequisite.read.Contract.Sparse)),
			"the conclusion preserves absence and never materializes a default")
	}

	invocation := map[string]string{fmt.Sprintf("input%d", prerequisite.position): fmt.Sprintf("input%d", prerequisite.position)}

	renderExecutePrologue(out, built)
	// The prerequisite's read is flat rather than a switch so its proved
	// region stays in scope for the fold: the published fact holds over what
	// this cell AND every observed member proved, and the emitted worker can
	// only pass regions it was handed - the mask type is the engine's own and
	// this file may not name it.
	fmt.Fprintf(out, "\tstatus := row.%s.Read(ticket, &lane.%s)\n", prerequisite.name, prerequisite.name)
	fmt.Fprintf(out, "\tif status == %s.ReadExhausted {\n", execution)
	fmt.Fprintf(out, "\t\tif !row.%s.Close(ticket, &lane.%s) {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", prerequisite.name, prerequisite.name, structure)
	fmt.Fprintf(out, "\t\treturn lane.settle(ticket, %s.NoCandidate)\n\t}\n", structure)
	fmt.Fprintf(out, "\tif status != %s.ReadAvailable {\n\t\t_ = lane.%s.Discard(ticket)\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n",
		execution, prerequisite.name, structure)
	fmt.Fprintf(out, "\tcell, available := lane.%s.Value()\n", prerequisite.name)
	fmt.Fprintf(out, "\tpresent := lane.%s.Present()\n", prerequisite.name)
	fmt.Fprintf(out, "\tregion, regionOK := lane.%s.Region()\n", prerequisite.name)
	fmt.Fprintf(out, "\tif !row.%s.Close(ticket, &lane.%s) {\n\t\t_ = lane.%s.Discard(ticket)\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n",
		prerequisite.name, prerequisite.name, prerequisite.name, structure)
	fmt.Fprintf(out, "\tif !available || !regionOK {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", structure)
	fmt.Fprintf(out, "\tcell, present = row.%sPolicy.Cell(cell, present)\n", prerequisite.name)
	fmt.Fprintf(out, "\tif !present {\n\t\treturn lane.settle(ticket, %s.NoCandidate)\n\t}\n", structure)
	fmt.Fprintf(out, "\tinput%d := cell\n", prerequisite.position)

	arguments := make([]string, 0, len(derivation.staticAxes)+len(derivation.arguments))
	for _, axis := range derivation.staticAxes {
		arguments = append(arguments, "lane.family."+axis.param)
	}
	for _, argument := range derivation.arguments {
		switch {
		case argument.candidate:
			arguments = append(arguments, "row.candidate")
		case argument.many:
			return unexpressible(built.target.Spec.Key, "a member set derived over another many-valued delivery",
				fmt.Sprintf("relation %q consumes the cells of join %d, which this form does not deliver to a derivation", selection.relation.Name, argument.join.position))
		default:
			arguments = append(arguments, fmt.Sprintf("input%d", argument.join.position))
		}
	}
	out.WriteString("\t// The member set is the relation's own answer, derived once per invocation\n")
	out.WriteString("\t// from the carriers its declaration names. Nothing below re-derives it.\n")
	fmt.Fprintf(out, "\tderived, derivedOK := %s\n", imports.call(derivation.build, "", arguments...))
	fmt.Fprintf(out, "\tif !derivedOK {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", structure)
	fmt.Fprintf(out, "\tcount := %s\n", imports.call(derivation.count, "", "derived"))
	fmt.Fprintf(out, "\tif count < 0 || count > len(lane.members) || count > len(lane.cells) {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", structure)
	out.WriteString("\tmembers := lane.members[:count]\n\tcells := lane.cells[:count]\n")
	out.WriteString("\tfor index := 0; index < count; index++ {\n")
	fmt.Fprintf(out, "\t\tselected, selectedOK := %s\n", imports.call(derivation.at, "", "derived", "index"))
	fmt.Fprintf(out, "\t\tif !selectedOK {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
	keyExpression, err := projectionExpression(built, selection.key, "selected", "\t\t", out)
	if err != nil {
		return err
	}
	tagExpression, err := projectionExpression(built, selection.predicate, "selected", "\t\t", out)
	if err != nil {
		return err
	}
	if selection.key.Result != selection.axis.source.Binding.Key.Carrier {
		return unexpressible(built.target.Spec.Key, "a selection key that is not the axis's own key carrier",
			fmt.Sprintf("projection %q publishes %s", selection.key.Name, selection.key.Result))
	}
	fmt.Fprintf(out, "\t\tdense, denseOK := %s\n", imports.call(selection.axis.normalizer, "lane.family."+selection.axis.param, keyExpression))
	fmt.Fprintf(out, "\t\tif !denseOK {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
	out.WriteString("\t\t// The member is the observation side alone. This row publishes at its own\n")
	out.WriteString("\t\t// candidate's coordinate, so no member of the selection is a destination.\n")
	fmt.Fprintf(out, "\t\tmember, memberOK := lane.family.plane.SelectedMember(uint32(dense), uint64(%s))\n", tagExpression)
	fmt.Fprintf(out, "\t\tif !memberOK {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", structure)
	out.WriteString("\t\tmembers[index] = member\n")
	out.WriteString("\t}\n")
	out.WriteString("\t// An empty derived relation is a read that named nothing, which is exhausted\n")
	out.WriteString("\t// rather than available; anything else is a selection that did not observe.\n")
	fmt.Fprintf(out, "\tobserved := row.%s.Observe(ticket, &lane.%s, members, cells)\n", selection.name, selection.name)
	out.WriteString("\tif count == 0 {\n")
	fmt.Fprintf(out, "\t\tif observed != %s.ReadExhausted {\n\t\t\treturn lane.settle(ticket, %s.Refuse)\n\t\t}\n", execution, structure)
	fmt.Fprintf(out, "\t} else if observed != %s.ReadAvailable {\n\t\treturn lane.settle(ticket, %s.Refuse)\n\t}\n", execution, structure)
	fmt.Fprintf(out, "\toutcome := %s.FoldSelectedExact(ticket, row.write, &lane.write, region, cells, %s{%s})\n",
		execution, reducerType, strings.Join(reducerLiteralFields(built, invocation), ", "))
	renderExecuteEpilogue(out, built)
	return nil
}

// declaredDerivations answers the derived joins whose construction this file
// writes, in declaration order.
func declaredDerivations(built *plan) []*joinPlan {
	joins := make([]*joinPlan, 0, len(built.joins))
	for _, join := range built.joins {
		if join.derivation != nil && join.derivation.declared != nil {
			joins = append(joins, join)
		}
	}
	return joins
}

// renderDeclaredDerivation writes one derived member set's whole construction:
// the rows it holds by value, the placement that keeps them canonical, and the
// Build that enumerates, resolves and places them.
//
// What is generated here is exactly what every authored Build wrote by hand -
// enumerate, resolve, union, widen at the endpoint, order, refuse a repeat -
// and the reason to generate it is that four of those five are the same in
// every one of them, and a mistake in any is a soundness mistake rather than a
// compile error.
func renderDeclaredDerivation(out *strings.Builder, built *plan, join *joinPlan) error {
	imports := built.imports
	declared := join.derivation.declared
	state := declared.state()
	entry := derivedMemberName(declared.position)
	width := derivedWidthName(declared.position)
	subject := imports.typeName(declared.subject)
	dense := imports.typeName(declared.order.normalized)
	tag := imports.typeName(declared.predicateType)

	fmt.Fprintf(out, "// %s is how many members join %d's set holds by value. It is the\n", width, declared.position)
	out.WriteString("// width its relation declares, which is that relation's own statement of how\n")
	out.WriteString("// many members it ordinarily answers.\n")
	fmt.Fprintf(out, "const %s = %d\n\n", width, declared.inlineWidth)

	fmt.Fprintf(out, "// %s is one member and the address it is reached at: the coordinate\n", entry)
	out.WriteString("// its relation's declared key normalizes to, and the tag its declared\n")
	out.WriteString("// predicate answers. Both are taken once, where the member is resolved,\n")
	out.WriteString("// because asking the owner for them again per comparison would let two\n")
	out.WriteString("// answers to one question disagree.\n")
	fmt.Fprintf(out, "type %s struct {\n\tdense %s\n\ttag   %s\n\trow   %s\n}\n\n", entry, dense, tag, subject)

	fmt.Fprintf(out, "// %s is the member set one invocation of join %d's declared relation\n", state, declared.position)
	out.WriteString("// answers. It is sealed by the Build below and read by nothing else.\n")
	out.WriteString("//\n")
	out.WriteString("// The ordinary answer is held BY VALUE in the bounded inline prefix and only a\n")
	out.WriteString("// wider one reaches the explicit spill, so an invocation answering within the\n")
	out.WriteString("// declared width allocates nothing at all.\n")
	fmt.Fprintf(out, "type %s struct {\n\tinline [%s]%s\n\tspill  []%s\n\tcount  int\n", state, width, entry, entry)
	if err := renderWidenedState(out, built, join); err != nil {
		return err
	}
	out.WriteString("}\n\n")

	fmt.Fprintf(out, "func %s(state %s) int { return state.count }\n\n", derivedCountName(declared.position), state)

	fmt.Fprintf(out, "// %s answers one member of the set together with the coordinate it\n", derivedMemberAtName(declared.position))
	out.WriteString("// is ordered at. The inline prefix holds the first members and the spill holds\n")
	out.WriteString("// the rest, in one order across both.\n")
	fmt.Fprintf(out, "func %s(state %s, index int) (%s, bool) {\n", derivedMemberAtName(declared.position), state, entry)
	if lazyWiden(declared) {
		out.WriteString("\t// A widened set placed nothing, so it holds no member here to answer with.\n")
		fmt.Fprintf(out, "\tif state.widened {\n\t\treturn %s{}, false\n\t}\n", entry)
	}
	fmt.Fprintf(out, "\tif index < 0 || index >= state.count {\n\t\treturn %s{}, false\n\t}\n", entry)
	out.WriteString("\tif index < len(state.inline) {\n\t\treturn state.inline[index], true\n\t}\n")
	fmt.Fprintf(out, "\tspilled := index - len(state.inline)\n\tif spilled >= len(state.spill) {\n\t\treturn %s{}, false\n\t}\n", entry)
	out.WriteString("\treturn state.spill[spilled], true\n}\n\n")

	fmt.Fprintf(out, "func %s(state %s, index int) (%s, bool) {\n", derivedAtName(declared.position), state, subject)
	if lazyWiden(declared) {
		fmt.Fprintf(out, "\tif state.widened {\n\t\treturn %s(state, index)\n\t}\n", derivedWidenedAtName(declared.position))
	}
	fmt.Fprintf(out, "\tmember, memberOK := %s(state, index)\n", derivedMemberAtName(declared.position))
	fmt.Fprintf(out, "\tif !memberOK {\n\t\tvar absent %s\n\t\treturn absent, false\n\t}\n", subject)
	out.WriteString("\treturn member.row, true\n}\n\n")

	renderDerivedInsert(out, built, declared)
	if lazyWiden(declared) {
		if err := renderDerivedWidenedAt(out, built, join); err != nil {
			return err
		}
	}
	return renderDerivedBuild(out, built, join)
}

// lazyWiden reports whether one derived set's widened answer is read where it
// lies rather than placed member by member.
func lazyWiden(declared *declaredPlan) bool {
	return declared.widen != nil && declared.widen.lazy
}

// widenedStateFields is what a lazily widened set has to keep to answer a
// member later: the axis schemas its judgment is resolved against and the
// candidate that judgment is about. They are the Build's own arguments, held
// by value, so keeping them copies nothing the invocation did not already have.
func widenedStateFields(built *plan, join *joinPlan) ([]string, []string, error) {
	derivation := join.derivation
	names := make([]string, 0, len(derivation.staticAxes)+1)
	types := make([]string, 0, len(derivation.staticAxes)+1)
	for _, axis := range derivation.staticAxes {
		names = append(names, prefixed("widen", axis.param))
		types = append(types, built.imports.typeName(axis.schemaType))
	}
	candidate, err := derivationArgumentType(built, derivation.arguments[derivation.declared.candidateArgument])
	if err != nil {
		return nil, nil, err
	}
	names = append(names, "widenCandidate")
	types = append(types, candidate)
	return names, types, nil
}

// renderWidenedState writes the fields a lazily widened set keeps.
func renderWidenedState(out *strings.Builder, built *plan, join *joinPlan) error {
	declared := join.derivation.declared
	if !lazyWiden(declared) {
		return nil
	}
	names, types, err := widenedStateFields(built, join)
	if err != nil {
		return err
	}
	out.WriteString("\n\t// A widened answer is the owner's whole directory, which already lies in\n")
	out.WriteString("\t// the order this relation is ordered by, so nothing above holds it: the set\n")
	out.WriteString("\t// records that it widened, the census it took, and the inputs one member is\n")
	out.WriteString("\t// resolved from, and answers each member on demand.\n")
	out.WriteString("\twidened bool\n")
	out.WriteString("\t// widenPrefix states that every member the directory yields contributes one\n")
	out.WriteString("\t// row, so an ordinal IS a directory position and no scan is needed.\n")
	out.WriteString("\twidenPrefix bool\n")
	for index, name := range names {
		fmt.Fprintf(out, "\t%s %s\n", name, types[index])
	}
	return nil
}

// renderDerivedWidenedAt writes the on-demand accessor of a widened set. It is
// what keeps widening from copying: the directory is read where it lies, and
// one member is resolved when it is asked for.
func renderDerivedWidenedAt(out *strings.Builder, built *plan, join *joinPlan) error {
	imports := built.imports
	declared := join.derivation.declared
	state := declared.state()
	subject := imports.typeName(declared.subject)
	source := declared.widen.sources[0]
	names, _, err := widenedStateFields(built, join)
	if err != nil {
		return err
	}
	over := "state." + prefixed("widen", source.axis.param)
	resolveArguments := make([]string, 0, len(names)+1)
	for _, name := range names {
		resolveArguments = append(resolveArguments, "state."+name)
	}
	resolve := func(item string) string {
		return imports.call(declared.widenJudgment(), "", append(append([]string{}, resolveArguments...), item)...)
	}

	fmt.Fprintf(out, "// %s answers one member of a widened set out of the directory it\n", derivedWidenedAtName(declared.position))
	out.WriteString("// lies in. Nothing was copied when the set was built, so the member is\n")
	out.WriteString("// resolved here, from the same inputs the census was taken over.\n")
	fmt.Fprintf(out, "func %s(state %s, index int) (%s, bool) {\n", derivedWidenedAtName(declared.position), state, subject)
	fmt.Fprintf(out, "\tvar absent %s\n", subject)
	out.WriteString("\tif !state.widened || index < 0 || index >= state.count {\n\t\treturn absent, false\n\t}\n")
	fmt.Fprintf(out, "\twidenCount := %s\n", source.census(imports, over))
	out.WriteString("\tif state.widenPrefix {\n")
	out.WriteString("\t\tif index >= widenCount {\n\t\t\treturn absent, false\n\t\t}\n")
	fmt.Fprintf(out, "\t\twidenItem, widenItemOK := %s\n", source.accessor(imports, over, "index"))
	out.WriteString("\t\tif !widenItemOK {\n\t\t\treturn absent, false\n\t\t}\n")
	fmt.Fprintf(out, "\t\twidenRow, widenPresent, widenResolved := %s\n", resolve("widenItem"))
	out.WriteString("\t\tif !widenResolved || !widenPresent {\n\t\t\treturn absent, false\n\t\t}\n")
	out.WriteString("\t\treturn widenRow, true\n\t}\n")
	out.WriteString("\t// The directory declines some of what it yields, so an ordinal is reached by\n")
	out.WriteString("\t// counting the members that contribute.\n")
	out.WriteString("\tordinal := 0\n")
	out.WriteString("\tfor widenCursor := 0; widenCursor < widenCount; widenCursor++ {\n")
	fmt.Fprintf(out, "\t\twidenItem, widenItemOK := %s\n", source.accessor(imports, over, "widenCursor"))
	out.WriteString("\t\tif !widenItemOK {\n\t\t\treturn absent, false\n\t\t}\n")
	fmt.Fprintf(out, "\t\twidenRow, widenPresent, widenResolved := %s\n", resolve("widenItem"))
	out.WriteString("\t\tif !widenResolved {\n\t\t\treturn absent, false\n\t\t}\n")
	out.WriteString("\t\tif !widenPresent {\n\t\t\tcontinue\n\t\t}\n")
	out.WriteString("\t\tif ordinal == index {\n\t\t\treturn widenRow, true\n\t\t}\n\t\tordinal++\n\t}\n")
	out.WriteString("\treturn absent, false\n}\n\n")
	return nil
}

// renderDerivedInsert writes the one admissible order of a member set as the
// placement that keeps it.
//
// The engine canonicalizes a selection by the coordinate its cells are read
// at, so ascending by the relation's own declared Key projection - normalized
// through the axis that numbers those coordinates - is not a choice. Keeping
// the set canonical while it is built means the order is never a second pass
// that could be written wrong, and it means a repeat is refused where it
// arrives: a selection carries one cell per member, and two rows on one
// coordinate have no second ordinal between them.
func renderDerivedInsert(out *strings.Builder, built *plan, declared *declaredPlan) {
	imports := built.imports
	state := declared.state()
	entry := derivedMemberName(declared.position)
	subject := imports.typeName(declared.subject)
	dense := imports.typeName(declared.order.normalized)
	tag := imports.typeName(declared.predicateType)
	insert := derivedInsertName(declared.position)

	fmt.Fprintf(out, "// %s places one resolved member at its canonical position.\n", insert)
	out.WriteString("//\n")
	out.WriteString("// The set is ordered ascending by the coordinate its relation's declared key\n")
	out.WriteString("// normalizes to, because that is the order the engine canonicalizes a\n")
	out.WriteString("// selection by.\n")
	out.WriteString("//\n")
	out.WriteString("// A member is reached at that coordinate AND at the tag its predicate\n")
	out.WriteString("// answers, and that pair is its whole address. Two items resolving to one\n")
	out.WriteString("// address are one member named twice - an alias of the same thing - and the\n")
	out.WriteString("// second adds no ordinal. Two items on one coordinate under DIFFERENT tags\n")
	out.WriteString("// are two members where a selection carries one cell, which has no answer\n")
	out.WriteString("// and is refused.\n")
	fmt.Fprintf(out, "func %s(built %s, dense %s, tag %s, row %s) (%s, bool) {\n", insert, state, dense, tag, subject, state)
	out.WriteString("\tposition := 0\n")
	out.WriteString("\tfor position < built.count {\n")
	fmt.Fprintf(out, "\t\tcurrent, currentOK := %s(built, position)\n", derivedMemberAtName(declared.position))
	fmt.Fprintf(out, "\t\tif !currentOK {\n\t\t\treturn %s{}, false\n\t\t}\n", state)
	out.WriteString("\t\tif current.dense == dense {\n")
	fmt.Fprintf(out, "\t\t\tif current.tag != tag {\n\t\t\t\treturn %s{}, false\n\t\t\t}\n", state)
	out.WriteString("\t\t\treturn built, true\n\t\t}\n")
	out.WriteString("\t\tif current.dense > dense {\n\t\t\tbreak\n\t\t}\n\t\tposition++\n\t}\n")
	fmt.Fprintf(out, "\tplaced := %s{dense: dense, tag: tag, row: row}\n", entry)
	out.WriteString("\tif built.count < len(built.inline) {\n")
	out.WriteString("\t\tfor index := built.count; index > position; index-- {\n\t\t\tbuilt.inline[index] = built.inline[index-1]\n\t\t}\n")
	out.WriteString("\t\tbuilt.inline[position] = placed\n\t\tbuilt.count++\n\t\treturn built, true\n\t}\n")
	out.WriteString("\t// The prefix is full. A member belonging inside it displaces the last one\n")
	out.WriteString("\t// held there, and that one takes the first spilled position instead.\n")
	out.WriteString("\tif position < len(built.inline) {\n")
	out.WriteString("\t\tcarried := built.inline[len(built.inline)-1]\n")
	out.WriteString("\t\tfor index := len(built.inline) - 1; index > position; index-- {\n\t\t\tbuilt.inline[index] = built.inline[index-1]\n\t\t}\n")
	out.WriteString("\t\tbuilt.inline[position] = placed\n\t\tplaced = carried\n\t\tposition = len(built.inline)\n\t}\n")
	out.WriteString("\tspilled := position - len(built.inline)\n")
	fmt.Fprintf(out, "\tif spilled > len(built.spill) {\n\t\treturn %s{}, false\n\t}\n", state)
	fmt.Fprintf(out, "\tbuilt.spill = append(built.spill, %s{})\n", entry)
	out.WriteString("\tcopy(built.spill[spilled+1:], built.spill[spilled:len(built.spill)-1])\n")
	out.WriteString("\tbuilt.spill[spilled] = placed\n\tbuilt.count++\n\treturn built, true\n}\n\n")
}

// renderDerivedBuild writes the construction itself: the endpoint test, the
// composed enumeration on either side of it, the one authored judgment per
// item, and the placement both answers leave through.
func renderDerivedBuild(out *strings.Builder, built *plan, join *joinPlan) error {
	imports := built.imports
	derivation := join.derivation
	declared := derivation.declared
	state := declared.state()

	parameters := make([]string, 0, len(derivation.staticAxes)+len(derivation.arguments))
	statics := make([]string, 0, len(derivation.staticAxes))
	for _, axis := range derivation.staticAxes {
		name := axis.param
		parameters = append(parameters, name+" "+imports.typeName(axis.schemaType))
		statics = append(statics, name)
	}
	arguments := make([]string, 0, len(derivation.arguments))
	for index, argument := range derivation.arguments {
		name := fmt.Sprintf("given%d", index)
		typeName, err := derivationArgumentType(built, argument)
		if err != nil {
			return err
		}
		parameters = append(parameters, name+" "+typeName)
		arguments = append(arguments, name)
	}

	fmt.Fprintf(out, "// %s answers join %d's member set for one invocation.\n", derivedBuildName(declared.position), declared.position)
	out.WriteString("// A source that reached its lattice endpoint named no alternatives at all, so\n")
	out.WriteString("// the answer there is the owner's whole directory rather than the ones that\n")
	out.WriteString("// happen to be written down. Both answers are placed the same way, so both\n")
	out.WriteString("// leave in the one order a selection is canonicalized by.\n")
	fmt.Fprintf(out, "func %s(%s) (%s, bool) {\n", derivedBuildName(declared.position), strings.Join(parameters, ", "), state)
	fmt.Fprintf(out, "\tvar built %s\n", state)

	var failed error
	refusal := fmt.Sprintf("return %s{}, false", state)
	// The coordinate a member is placed at is taken through the relation's own
	// declared Key projection, destructured the way its owner wrote it.
	coordinate := func(indent, row string) string {
		name, err := projectionExpressionRefusing(built, declared.key, row, indent, refusal, out)
		if err != nil {
			failed = err
			return "key"
		}
		return name
	}
	address := func(indent, row string) (string, string) {
		key := coordinate(indent, row)
		predicate, err := projectionExpressionRefusing(built, declared.predicate, row, indent, refusal, out)
		if err != nil {
			failed = err
			predicate = "tag"
		}
		return key, predicate
	}
	place := func(indent, row string) {
		key, tag := address(indent, row)
		fmt.Fprintf(out, "%sdense, denseOK := %s\n", indent, imports.call(declared.order.normalizer, declared.order.param, key))
		fmt.Fprintf(out, "%sif !denseOK {\n%s\t%s\n%s}\n", indent, indent, refusal, indent)
		fmt.Fprintf(out, "%svar placed bool\n", indent)
		fmt.Fprintf(out, "%sbuilt, placed = %s(built, dense, %s, %s)\n", indent, derivedInsertName(declared.position), tag, row)
		fmt.Fprintf(out, "%sif !placed {\n%s\t%s\n%s}\n", indent, indent, refusal, indent)
	}
	resolve := func(indent string, judgment definition.GoSymbol, item, row string) {
		call := imports.call(judgment, "", append(append([]string{}, statics...), arguments[declared.candidateArgument], item)...)
		fmt.Fprintf(out, "%s%s, present, resolved := %s\n", indent, row, call)
		fmt.Fprintf(out, "%sif !resolved {\n%s\treturn %s{}, false\n%s}\n", indent, indent, state, indent)
		fmt.Fprintf(out, "%sif present {\n", indent)
		place(indent+"\t", row)
		fmt.Fprintf(out, "%s}\n", indent)
	}
	walk := func(sources []enumerationPlan, judgment definition.GoSymbol, root, prefix, indent string) {
		over := root
		for level, source := range sources {
			count := prefixed(prefix, fmt.Sprintf("count%d", level))
			cursor := prefixed(prefix, fmt.Sprintf("cursor%d", level))
			item := prefixed(prefix, fmt.Sprintf("item%d", level))
			fmt.Fprintf(out, "%s%s := %s\n", indent, count, source.census(imports, over))
			fmt.Fprintf(out, "%sfor %s := 0; %s < %s; %s++ {\n", indent, cursor, cursor, count, cursor)
			indent += "\t"
			fmt.Fprintf(out, "%s%s, %sOK := %s\n", indent, item, item, source.accessor(imports, over, cursor))
			fmt.Fprintf(out, "%sif !%sOK {\n%s\treturn %s{}, false\n%s}\n", indent, item, indent, state, indent)
			over = item
		}
		resolve(indent, judgment, over, prefixed(prefix, "row"))
		for level := len(sources) - 1; level >= 0; level-- {
			indent = indent[:len(indent)-1]
			fmt.Fprintf(out, "%s}\n", indent)
		}
	}

	if declared.widen != nil {
		// The endpoint is a judgment over what Resolve is a judgment over,
		// minus the item there is not one of yet.
		endpoint := imports.call(declared.widen.predicate, "",
			append(append([]string{}, statics...), arguments[declared.candidateArgument], arguments[declared.sourceArgument])...)
		out.WriteString("\t// The endpoint is the one judgment that runs whether or not the source\n")
		out.WriteString("\t// yields anything, so it is where an invocation nothing else would look at\n")
		out.WriteString("\t// is authenticated.\n")
		fmt.Fprintf(out, "\tbeyond, admissible := %s\n", endpoint)
		fmt.Fprintf(out, "\tif !admissible {\n\t\t%s\n\t}\n", refusal)
		out.WriteString("\tif beyond {\n")
		// The widened answer is read out of the owner's own schema, so its
		// outer level starts from that axis rather than from the value.
		if lazyWiden(declared) {
			if err := renderLazyWiden(out, built, join, statics, arguments); err != nil {
				return err
			}
		} else {
			walk(declared.widen.sources, declared.widenJudgment(), declared.widen.sources[0].axis.param, "widen", "\t\t")
		}
		out.WriteString("\t\treturn built, true\n\t}\n")
	}
	walk(declared.sources, declared.resolve, arguments[declared.sourceArgument], "", "\t")
	out.WriteString("\treturn built, true\n}\n\n")
	return failed
}

// renderLazyWiden writes the widened arm of a set that is read where it lies.
//
// Nothing is placed. The arm keeps what one member is resolved from, censuses
// the directory once, and holds that directory to the promise the laziness
// rests on: the coordinates it yields are strictly ascending, or the answer is
// refused rather than answered in an order it never had.
func renderLazyWiden(out *strings.Builder, built *plan, join *joinPlan, statics, arguments []string) error {
	imports := built.imports
	declared := join.derivation.declared
	state := declared.state()
	source := declared.widen.sources[0]
	dense := imports.typeName(declared.order.normalized)
	names, _, err := widenedStateFields(built, join)
	if err != nil {
		return err
	}
	kept := append(append([]string{}, statics...), arguments[declared.candidateArgument])
	over := source.axis.param

	out.WriteString("\t\tbuilt.widened = true\n\t\tbuilt.widenPrefix = true\n")
	for index, name := range names {
		fmt.Fprintf(out, "\t\tbuilt.%s = %s\n", name, kept[index])
	}
	fmt.Fprintf(out, "\t\tvar widenPrevious %s\n", dense)
	out.WriteString("\t\tvar widenSeen bool\n\t\tvar widenGap bool\n")
	fmt.Fprintf(out, "\t\twidenCount := %s\n", source.census(imports, over))
	out.WriteString("\t\tfor widenCursor := 0; widenCursor < widenCount; widenCursor++ {\n")
	fmt.Fprintf(out, "\t\t\twidenItem, widenItemOK := %s\n", source.accessor(imports, over, "widenCursor"))
	fmt.Fprintf(out, "\t\t\tif !widenItemOK {\n\t\t\t\treturn %s{}, false\n\t\t\t}\n", state)
	call := imports.call(declared.widenJudgment(), "", append(append([]string{}, kept...), "widenItem")...)
	fmt.Fprintf(out, "\t\t\twidenRow, widenPresent, widenResolved := %s\n", call)
	fmt.Fprintf(out, "\t\t\tif !widenResolved {\n\t\t\t\treturn %s{}, false\n\t\t\t}\n", state)
	out.WriteString("\t\t\tif !widenPresent {\n\t\t\t\twidenGap = true\n\t\t\t\tcontinue\n\t\t\t}\n")
	out.WriteString("\t\t\tif widenGap {\n\t\t\t\tbuilt.widenPrefix = false\n\t\t\t}\n")
	refusal := fmt.Sprintf("return %s{}, false", state)
	key, keyErr := projectionExpressionRefusing(built, declared.key, "widenRow", "\t\t\t", refusal, out)
	if keyErr != nil {
		return keyErr
	}
	fmt.Fprintf(out, "\t\t\tdense, denseOK := %s\n", imports.call(declared.order.normalizer, declared.order.param, key))
	fmt.Fprintf(out, "\t\t\tif !denseOK {\n\t\t\t\t%s\n\t\t\t}\n", refusal)
	fmt.Fprintf(out, "\t\t\tif widenSeen && dense <= widenPrevious {\n\t\t\t\treturn %s{}, false\n\t\t\t}\n", state)
	out.WriteString("\t\t\twidenPrevious, widenSeen = dense, true\n")
	out.WriteString("\t\t\tbuilt.count++\n\t\t}\n")
	return nil
}

// prefixed spells one generated local under the arm it belongs to, so the
// widened arm and the ordinary one never name the same variable.
func prefixed(prefix, base string) string {
	if prefix == "" {
		return base
	}
	return prefix + strings.ToUpper(base[:1]) + base[1:]
}

// derivationArgumentType spells the Go type one derivation argument arrives as.
func derivationArgumentType(built *plan, argument derivationArg) (string, error) {
	imports := built.imports
	if argument.candidate {
		return imports.typeName(built.candidate.subject), nil
	}
	if argument.many {
		return "", unexpressible(built.target.Spec.Key, "a generated derivation over a many-valued delivery",
			"a declared derivation reads its items out of a value, and a whole delivery has no generated enumeration yet")
	}
	return imports.typeName(argument.join.axis.fact), nil
}

// state is the generated name of one derived member set's sealed rows.
func (declared *declaredPlan) state() string { return derivedStateName(declared.position) }
